-- Registre de lancement : noms HELIO (transcodification validée par le client le 2026-10-31) dans la colonne produit.
UPDATE "LaunchInput" SET "product" = regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace("product",
  'HelioRoof Screen', 'HelioRoof', 'g'), '\mMarbella\M', 'HelioMax', 'g'), '\mSevilla\M', 'HelioLux', 'g'), '\mMalaga\M', 'HelioSky', 'g'),
  '\mCasablanca\M', 'HelioSun', 'g'), '\mCorsica\M', 'HelioShade', 'g'), '\mJamaica\M', 'HelioPro', 'g'), '\mMadera\M', 'HelioSquare', 'g'), '\mSevillia\M', 'HelioLux', 'g'),
  "updatedAt" = NOW()
WHERE "product" ~ '(HelioRoof Screen|\mMarbella\M|\mSevillia?\M|\mMalaga\M|\mCasablanca\M|\mCorsica\M|\mJamaica\M|\mMadera\M)';

